		return true
	}
	if q == "*" {
		return true
	}
	if strings.HasSuffix(q, "*") && !strings.ContainsAny(q[:len(q)-1], "*?[") {
		prefix := q[:len(q)-1]
		return strings.HasPrefix(p, prefix)
	}
	return false
}

// addedPatterns returns patterns in newPatterns that are not covered by any
// pattern in oldPatterns (i.e. genuinely new action/role space).
func addedPatterns(oldPatterns, newPatterns []string) []string {
	var out []string
	for _, n := range newPatterns {
		covered := false
		for _, o := range oldPatterns {
			if patternCovers(o, n) {
				covered = true
				break
			}
		}
		if !covered {
			out = append(out, n)
		}
	}
	return out
}

// removedPatterns returns patterns in oldPatterns whose covered space is not
// covered by any pattern in newPatterns.
func removedPatterns(oldPatterns, newPatterns []string) []string {
	var out []string
	for _, o := range oldPatterns {
		covered := false
		for _, n := range newPatterns {
			if patternCovers(n, o) {
				covered = true
				break
			}
		}
		if !covered {
			out = append(out, o)
		}
	}
	return out
}

// retainedPatterns returns the old/new pattern pairs that cover the same
// literal space, used for effect/condition comparison.
func retainedPatterns(oldPatterns, newPatterns []string) (oldRetained, newRetained []string) {
	for _, o := range oldPatterns {
		for _, n := range newPatterns {
			if o == n || patternCovers(n, o) && patternCovers(o, n) {
				oldRetained = append(oldRetained, o)
				newRetained = append(newRetained, n)
				break
			}
		}
	}
